INSERT INTO feature VALUES('rendered-captures','editor','Rendered captures of the panes','visual-language','implemented','ordinary',NULL,'Each pane of the side view renders over the recorded frames of a scene into SVG through the view''s own layout: one `<tspan>` per cell at its column, and each warrant''s hue a CSS variable of its colour''s name. A test replays the frames through the view, checks each state against the rules of the visual language, and compares each capture with its committed file, so a changed renderer changes the capture and its diff shows the cells that moved. The warrants scene and the schedule scene have their captures; each other pane adds its own with this harness.','surface-tui','crates/surface-tui/tests/captures.rs crates/surface-tui/src/capture.rs','crate-tests','#6303');
